SELECT "tradeid", "sk_brokerid", "sk_createdateid", "sk_createtimeid", "sk_closedateid", "sk_closetimeid", "status", "dt_type", "cashflag", "sk_securityid", "sk_companyid", "quantity", "bidprice", "sk_customerid", "sk_accountid", "executedby", "tradeprice", "fee", "commission", "tax", "batchid" FROM (SELECT TRY_CAST((CAST(t.T_ID AS INT)) AS INT) AS "tradeid", TRY_CAST((CAST(NULL AS INT)) AS INT) AS "sk_brokerid", TRY_CAST((CAST(STRFTIME(t.T_DTS, '%Y%m%d') AS INT)) AS INT) AS "sk_createdateid", TRY_CAST((CAST(STRFTIME(t.T_DTS, '%Y%m%d') AS INT)) AS INT) AS "sk_createtimeid", TRY_CAST((CAST(STRFTIME(t.T_DTS, '%Y%m%d') AS INT)) AS INT) AS "sk_closedateid", TRY_CAST((CAST(NULL AS INT)) AS INT) AS "sk_closetimeid", TRY_CAST((CAST(t.T_ST_ID AS TEXT)) AS TEXT) AS "status", TRY_CAST((CAST(tt.TT_NAME AS TEXT)) AS TEXT) AS "dt_type", TRY_CAST((CASE WHEN t.T_IS_CASH = '1' THEN TRUE WHEN t.T_IS_CASH = '0' THEN FALSE ELSE NULL END) AS BOOLEAN) AS "cashflag", TRY_CAST((CAST(NULL AS INT)) AS INT) AS "sk_securityid", TRY_CAST((CAST(NULL AS INT)) AS INT) AS "sk_companyid", TRY_CAST((t.T_QTY) AS DECIMAL(6, 0)) AS "quantity", TRY_CAST((CAST(t.T_BID_PRICE AS DECIMAL(8, 2))) AS DECIMAL(8, 2)) AS "bidprice", TRY_CAST((CAST(NULL AS INT)) AS INT) AS "sk_customerid", TRY_CAST((CAST(t.T_CA_ID AS INT)) AS INT) AS "sk_accountid", TRY_CAST((CAST(t.T_EXEC_NAME AS TEXT)) AS TEXT) AS "executedby", TRY_CAST((t.T_TRADE_PRICE) AS DECIMAL(8, 2)) AS "tradeprice", TRY_CAST((t.T_CHRG) AS DECIMAL(10, 2)) AS "fee", TRY_CAST((t.T_COMM) AS DECIMAL(10, 2)) AS "commission", TRY_CAST((t.T_TAX) AS DECIMAL(10, 2)) AS "tax", TRY_CAST((CAST(NULL AS DECIMAL(5))) AS DECIMAL(5)) AS "batchid" FROM "Source"."Trade" AS t LEFT JOIN "Source"."StatusType" AS st ON t.T_ST_ID = st.ST_ID LEFT JOIN "Source"."TradeType" AS tt ON t.T_TT_ID = tt.TT_ID);
